{
  "gate_token": "OtHuvWBg4yP1Zfr--eSbyA",
  "title": "The Mirror Road Through the Broken Capital",
  "scenes": [
    {
      "scene_number": 1,
guides
      "caption": "Mara unrolls a map of the ruined capital at dawn.",
      "visual_description": "A windswept ridge overlooking a shattered skyline of toppled spires; Mara kneels with a parchment weighted by her brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of three false paths.",
      "visual_description": "A small oil lamp glows on a stone cairn, its single flame-eye narrowed; smoke curls into the shape of three forking roads.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox sniffs out a hidden mirror entrance.",
      "visual_description": "A clockwork fox with blue glass eyes paws at a cracked silver mirror leaning in the rubble of a fallen archway.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver surfaces from the mirror's silver pool.",
      "visual_description": "A figure in a clear diving helmet rises out of the mirror as if from water, coat shimmering with reflected broken city lights.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The team passes the looming castle gates.",
      "visual_description": "Enormous iron gates hang crooked from their hinges; faded royal banners flap above as the small party slips beneath.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "A round official snores on a toll booth desk, ledger as pillow, stamped papers stuck to his sleeves, ink pooling on a half-finished form.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns away from the cursed tower.",
      "visual_description": "A black spiral tower leans over a courtyard; the lamp's flame flares red, casting warning shadows on cracked flagstones.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Townsfolk rumors of a winged beast slow the team.",
      "visual_description": "Empty market stalls, scorched shingles, and a hand-painted sign showing a winged silhouette; Mara studies it with a frown.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "An armored patrol passes; Tin Fox freezes into a statue.",
      "visual_description": "Lantern light sweeps a colonnade as the clockwork fox stiffens beside a bronze pedestal, indistinguishable from old metalwork.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The Glass Diver slips through a stained window to scout.",
      "visual_description": "Coat rippling like liquid, the diver melts halfway into a tall cathedral window, only their boots still on the cobblestones.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Mara maps the rune-locked magic door.",
      "visual_description": "A massive door covered in concentric glowing rings; Mara sketches the pattern by lamp light, compass spinning wildly.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Tin Fox's key-wind tail clicks the final rune into place.",
      "visual_description": "The fox stands on hind paws, brass tail rotating against a glyph; the door's rings align in a shaft of pale gold light.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Inside the throne hall, they find the prisoner: the sleeping tax collector again, chained.",
      "visual_description": "Under a torn royal banner, the same round official is shackled to a broken throne, still dozing, dream-bubbles rising from his hat.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp reveals he holds the city's stolen treaty in his ledger.",
      "visual_description": "Light from the lamp's eye spills across the ledger, exposing a folded parchment seal hidden between pages of tax stamps.",
      "characters": ["oracle_lamp", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Alarms ring; the Glass Diver pulls the sleeper through a window.",
      "visual_description": "Bells jangle on broken towers as the diver hauls the snoring official halfway into a rippling pane of leaded glass.",
      "characters": ["glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Patrol lanterns close in along the rooftop run.",
      "visual_description": "Mara and Tin Fox sprint over tiled roofs, distant armored figures fanning out below with bobbing lights.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They race onto the long bridge over the moat-river.",
      "visual_description": "A narrow stone bridge stretches between ruined banks; the team runs across as planks crack and royal banners tumble into the water.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, Mara marks the route closed forever.",
      "visual_description": "Dawn behind them, the broken capital silhouetted across the river; Mara draws a final ink cross on her map as Tin Fox curls at her boots.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

